class Solution {
public:
    long long minimumDifference(vector<int>& nums) {
        int m = nums.size();
        int n = m / 3;

        vector<long long> leftMin(m, 0);
        priority_queue<int> maxHeap;
        long long sum = 0;
        for (int i = 0; i < n; i++) {
            maxHeap.push(nums[i]);
            sum += nums[i];
        }
        leftMin[n - 1] = sum;
        for (int i = n; i < 2 * n; i++) {
            if (nums[i] < maxHeap.top()) {
                sum -= maxHeap.top();
                maxHeap.pop();
                maxHeap.push(nums[i]);
                sum += nums[i];
            }
            leftMin[i] = sum;
        }

        vector<long long> rightMax(m, 0);
        priority_queue<int, vector<int>, greater<int>> minHeap;
        sum = 0;
        for (int i = 2 * n; i < 3 * n; i++) {
            minHeap.push(nums[i]);
            sum += nums[i];
        }
        rightMax[2 * n] = sum;
        for (int i = 2 * n - 1; i >= n; i--) {
            if (nums[i] > minHeap.top()) {
                sum -= minHeap.top();
                minHeap.pop();
                minHeap.push(nums[i]);
                sum += nums[i];
            }
            rightMax[i] = sum;
        }

        long long ans = LLONG_MAX;
        for (int i = n - 1; i <= 2 * n - 1; i++) {
            ans = min(ans, leftMin[i] - rightMax[i + 1]);
        }
        return ans;
    }
};
